  return seq<T>(x, x);
}

pure function first<T>(sequence: Seq<T>): T {
  return index(sequence, 0n);
}

pure function pack<T>(x: T): Pair {
  return ({ first: x, second: x } satisfies Pair);
}

pure function choose<T>(x: T, y: T): T {
  return y;
}

pure function map<T>(sequence: Seq<T>): Seq<T> {
  return seqMap(sequence, id);
}

pure function fold<T>(sequence: Seq<T>, x: T): T {
  return seqFold(sequence, x, choose);
}

